/**
 * SQL table shapes (MySQL + PostgreSQL) for Kysely. Conventions (database-safety rule):
 * - money in integer paise (`integer`), never float;
 * - times as `datetime(3)` (MySQL, UTC session) / `timestamptz(3)` (PostgreSQL), read back as Date;
 * - ids are opaque strings generated by the app (`cus_…`), so the same ids work on MongoDB;
 * - flexible, non-queried data in JSON columns only.
 */
export interface ConsentRecordsTable {
  id: string;
  user_id: string | null;
  visitor_id: string | null;
  subscriber_id: string | null;
  purpose: string;
  status: string;
  method: string;
  source: string;
  notice_version: string;
  ip_address: string;
  user_agent: string;
  created_at: Date;
}

export interface CustomersTable {
  id: string;
  phone: string;
  name: string | null;
  email: string | null;
  created_at: Date;
  order_count: number;
  /** JSON object: coupon code → uses. */
  coupon_uses: string | Record<string, number>;
  cod_blocked: boolean | number;
  rto_count: number;
  erased_at: Date | null;
}

export interface CustomerAddressesTable {
  id: string;
  customer_id: string;
  position: number;
  name: string;
  phone: string;
  pincode: string;
  line1: string;
  line2: string;
  landmark: string;
  city: string;
  state: string;
  type: string;
}

export interface SessionsTable {
  token_hash: string;
  customer_id: string;
  created_at: Date;
  expires_at: Date;
}

export interface OtpChallengesTable {
  id: string;
  phone: string;
  code_hash: string;
  expires_at: Date;
  attempts: number;
  used: boolean | number;
}

export interface OtpSendsTable {
  id: string;
  phone: string;
  sent_at: Date;
}

export interface Database {
  consent_records: ConsentRecordsTable;
  customers: CustomersTable;
  customer_addresses: CustomerAddressesTable;
  sessions: SessionsTable;
  otp_challenges: OtpChallengesTable;
  otp_sends: OtpSendsTable;
}
